mapper.select:
SELECT t.id AS id, t.task_no AS taskNo, t.created_by_id AS createdById, t.created_by_username AS createdByUsername, t.user_status AS userStatus, t.template_id AS templateId, t.template_name AS templateName, t.template_version AS templateVersion, t.template_snapshot AS templateSnapshot, t.description AS description, t.total_count AS totalCount, t.success_count AS successCount, t.failed_count AS failedCount, t.total_duration_ms AS totalDurationMs, t.total_size AS totalSize, t.result_zip_key AS resultZipKey, t.report AS report, t.started_at AS startedAt, t.finished_at AS finishedAt, t.created_at AS createdAt, 'completed' AS status, COALESCE(( SELECT SUM(p.points) FROM tw_point_change_log p WHERE p.source_type = 'batch_task' AND p.source_id = t.task_no AND p.change_type = 'deduct' ), 0) AS deductedPoints, GREATEST( COALESCE(( SELECT SUM(p.points) FROM tw_point_change_log p WHERE p.source_type = 'batch_task' AND p.source_id = t.task_no AND p.change_type = 'deduct' ), 0) - COALESCE(( SELECT SUM(p.points) FROM tw_point_change_log p WHERE p.source_type = 'batch_task' AND p.source_id = t.task_no AND p.change_type = 'refund' ), 0), 0 ) AS consumedPoints, COALESCE(( SELECT SUM(p.points) FROM tw_point_change_log p WHERE p.source_type = 'batch_task' AND p.source_id = t.task_no AND p.change_type = 'refund' ), 0) AS refundedPoints FROM tw_batch_task t WHERE t.team_id = #{teamId} AND t.finished_at IS NOT NULL AND EXISTS ( SELECT 1 FROM tw_point_change_log p WHERE p.source_type = 'batch_task' AND p.source_id = t.task_no AND p.change_type = 'refund' )
AND 1 = 0
AND t.created_by_username LIKE CONCAT('%', #{operatorKeyword}, '%')
AND t.template_name LIKE CONCAT('%', #{templateName}, '%')
AND t.task_no LIKE CONCAT('%', #{taskNo}, '%')
AND t.created_at >= #{startTime}
AND t.created_at <= #{endTime}
ORDER BY t.finished_at DESC, t.created_at DESC LIMIT #{offset}, #{size}
